(()=>{const video=document.querySelector('#grill-video'),toggle=document.querySelector('.video-toggle');if(video&&toggle){const reduced=matchMedia('(prefers-reduced-motion: reduce)');function label(){toggle.textContent=video.paused?'Play animation ▷':'Pause animation Ⅱ';toggle.setAttribute('aria-label',video.paused?'Play grilling animation':'Pause grilling animation')}if(reduced.matches){video.autoplay=false;video.pause()}toggle.addEventListener('click',()=>{if(video.paused)video.play().catch(()=>{});else video.pause()});video.addEventListener('play',label);video.addEventListener('pause',label);label();}})();